'use strict';
// Meeting identity and filters are shared by the timeline, topic views and exports.
const mtBase={workbench,aaResultTools,awMeeting,awMeetingRegular,awMeetingRisk,meetingFilterModal,handleAction};
const mtViews=new Map();
function mtDate(row){const value=String(row.date||'').trim(),match=value.match(/^(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})(?:日|$|[T\s])/);if(!match)return '';const y=+match[1],m=+match[2],d=+match[3],date=new Date(Date.UTC(y,m-1,d));return date.getUTCFullYear()===y&&date.getUTCMonth()===m-1&&date.getUTCDate()===d?`${match[1]}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:'';}
function mtMeetingKey(row){return awMeetingIdentity(row);}
function mtTopic(row){return String(row.topic||row.clusterName||'未归类议题');}
function mtMeetings(rows){const groups=new Map();for(const row of rows){const key=mtMeetingKey(row);if(!groups.has(key))groups.set(key,{key,title:row.title||'未提取到会议名称',date:mtDate(row),rows:[]});groups.get(key).rows.push(row);}return [...groups.values()].sort((a,b)=>a.date&&b.date?a.date.localeCompare(b.date):a.date?-1:b.date?1:0);}
function mtDates(rows){const groups=new Map();for(const meeting of mtMeetings(rows)){if(!groups.has(meeting.date))groups.set(meeting.date,{date:meeting.date,meetings:[]});groups.get(meeting.date).meetings.push(meeting);}return [...groups.values()];}
function mtTopics(rows,order='desc'){const groups=new Map();for(const row of rows){const key=mtTopic(row);if(!groups.has(key))groups.set(key,{name:key,rows:[]});groups.get(key).rows.push(row);}return [...groups.values()].sort((a,b)=>(order==='asc'?1:-1)*(a.rows.length-b.rows.length)||a.name.localeCompare(b.name,'zh-CN'));}
function mtColor(topic){let h=0;for(const c of topic)h=(h*31+c.charCodeAt(0))|0;return ['#2868bf','#7a5aac','#288172','#b37b23','#ba5b56','#52778d'][Math.abs(h)%6];}
function mtState(task,rows=awMeetingFiltered(task)){if(!mtViews.has(task.id))mtViews.set(task.id,{page:1,topicPage:1,detailPage:1,topic:'',meeting:'',focus:-1,dates:new Set(),meetings:new Set(),limits:{},order:'desc',pane:'timeline',initialized:false});const v=mtViews.get(task.id),dates=mtDates(rows),signature=JSON.stringify([av('meeting').resultQuery,av('meeting').resultScope,av('meeting').resultFolder,task.meetingFilters]);if(v.signature!==signature){v.signature=signature;v.page=1;v.topicPage=1;v.detailPage=1;if(!rows.some(r=>mtTopic(r)===v.topic))v.topic='';if(!rows.some(r=>mtMeetingKey(r)===v.meeting))v.meeting='';if(!rows.includes(task.result[v.focus]))v.focus=-1;}
 if(!v.initialized&&dates.length){v.initialized=true;dates.slice(0,2).forEach(d=>v.dates.add(d.date));v.meetings.add(dates[0].meetings[0].key);v.meeting=dates[0].meetings[0].key;}if(!v.topic&&!v.meeting&&dates.length){v.meeting=dates[0].meetings[0].key;v.dates.add(dates[0].date);v.meetings.add(v.meeting);}v.page=Math.max(1,Math.min(v.page,Math.ceil(dates.length/8)||1));return v;}
awMeetingFiltered=function(task){const f=task.meetingFilters;if(!f)return awRows(task);const names=String(f.participants||'').split(/[|、，,；;\n]+/).map(s=>s.trim()).filter(Boolean),min=f.min!=null&&String(f.min).trim()!=='',max=f.max!=null&&String(f.max).trim()!=='';let pattern=null;if(f.keywords&&f.regex){try{pattern=safePattern(f.keywords);}catch{return [];}}return awRows(task).filter(row=>{const people=[row.participants,row.observers].map(ewDisplay).join(' '),date=mtDate(row);if(names.length&&!names.some(n=>people.includes(n)))return false;if((f.from||f.to)&&!date||f.from&&date<f.from||f.to&&date>f.to)return false;const amount=Number.parseFloat(String(row.amount??'').replace(/[,，]/g,''));if((min||max)&&!Number.isFinite(amount)||min&&amount<+f.min||max&&amount>+f.max)return false;const text=[row.topicName,mtTopic(row),row.excerpt].join(' ');if(f.keywords){if(pattern){pattern.lastIndex=0;if(!pattern.test(text))return false;}else if(!text.toLowerCase().includes(String(f.keywords).toLowerCase()))return false;}return true;});};
function mtFilterEntries(task){const f=task.meetingFilters||{},entries=[];if(String(f.participants||'').trim())entries.push(['人员',String(f.participants).trim()]);if(f.from||f.to)entries.push(['会议时间',(f.from||'不限')+' 至 '+(f.to||'不限')]);const min=f.min!=null&&String(f.min).trim()!=='',max=f.max!=null&&String(f.max).trim()!=='';if(min||max)entries.push(['金额',(min?f.min:'不限')+' 至 '+(max?f.max:'不限')+' 万元']);if(String(f.keywords||'').trim())entries.push([f.regex?'关键词（正则）':'关键词',f.keywords]);return entries;}
aaResultTools=function(task,risk=false){const html=mtBase.aaResultTools(task,risk);if(task.toolId!=='meeting')return html;const root=document.createElement('div');root.innerHTML=html;const entries=mtFilterEntries(task),button=root.querySelector('[data-action=meeting-filter]');if(button){button.textContent='筛选条件'+(entries.length?' · '+entries.length:'');button.className='btn '+(entries.length?'soft ':'')+'sm';button.setAttribute('aria-label','筛选会议分析结果'+(entries.length?'，已应用'+entries.length+'项条件':''));}return root.innerHTML+(entries.length?'<div class="mt-filter-summary" role="status" aria-label="已应用的筛选条件"><span>已筛选</span>'+entries.map(([label,value])=>'<span class="mt-filter-chip" title="'+E(label+'：'+value)+'">'+E(label)+'：'+E(value)+'</span>').join('')+'</div>':'');};
meetingFilterModal=function(){const root=document.createElement('div');root.innerHTML=mtBase.meetingFilterModal();root.querySelector('.modalhead h2').textContent='筛选条件';root.querySelector('.modalhead p').textContent='筛选本次会议分析结果，同步更新会议时间轴、议题聚类和详情。';const labels={participants:'参会 / 列席人员',from:'开始日期',to:'结束日期',min:'最小金额（万元）',max:'最大金额（万元）',keywords:'关键词搜索'},inputs={};for(const [key,label] of Object.entries(labels)){const input=root.querySelector('[data-edit='+key+']');input.id='mt-filter-'+key;input.setAttribute('aria-label',label);inputs[key]=input.outerHTML;}const field=(label,key,content,help='')=>'<div class="mt-filter-field"><label for="mt-filter-'+key+'">'+label+'</label>'+content+(help?'<p>'+help+'</p>':'')+'</div>',range=(a,b)=>'<div class="mt-filter-range">'+inputs[a]+'<span>至</span>'+inputs[b]+'</div>';const grid=root.querySelector('.filter-grid');grid.classList.add('mt-filter-grid');grid.innerHTML=field('参会 / 列席人员','participants',inputs.participants,'多个姓名用顿号分隔，匹配任一人员。')+field('时间范围','from',range('from','to'))+field('金额范围（万元）','min',range('min','max'),'未提取到金额的议题不参与金额范围筛选。')+field('关键词搜索','keywords',inputs.keywords);root.querySelector('[data-edit=participants]').placeholder='例如：张华、李宁';root.querySelector('[data-edit=keywords]').placeholder='查找议题名称、内容或聚类名称';root.querySelector('[data-edit=min]').placeholder='最小金额';root.querySelector('[data-edit=max]').placeholder='最大金额';root.querySelectorAll('[data-edit=min],[data-edit=max]').forEach(input=>input.step='any');const regex=root.querySelector('.aa-regex');if(regex){regex.querySelector('summary').textContent='正则表达式（高级）';const label=regex.querySelector('label');if(label)label.lastChild.textContent=' 使用正则表达式';}root.querySelector('[data-action=v2-reset-meeting-filter]').textContent='清空条件';return root.innerHTML;};
function mtPage(kind,count,page,size,unit){if(count<=size)return '';return '<footer class="mt-pager"><span>共 <strong>'+count+'</strong> '+unit+'</span><div>'+B('上一页','mt-page','ghost sm','data-kind="'+kind+'" data-step="-1" '+(page<=1?'disabled':''))+'<span>'+page+' / '+Math.ceil(count/size)+'</span>'+B('下一页','mt-page','ghost sm','data-kind="'+kind+'" data-step="1" '+(page>=Math.ceil(count/size)?'disabled':''))+'</div></footer>';}
function mtTimeline(task,rows){const v=mtState(task,rows),dates=mtDates(rows),known=dates.filter(d=>d.date),meetings=mtMeetings(rows),topics=mtTopics(rows,v.order),selected=v.topic?rows.filter(r=>mtTopic(r)===v.topic):rows.filter(r=>mtMeetingKey(r)===v.meeting),details=[...selected].sort((a,b)=>(mtDate(a)||'9999').localeCompare(mtDate(b)||'9999'));v.topicPage=Math.max(1,Math.min(v.topicPage,Math.ceil(topics.length/8)||1));v.detailPage=Math.max(1,Math.min(v.detailPage,Math.ceil(details.length/12)||1));
 return '<div class="mt-mobile-switch" aria-label="时间轴阅读区域">'+[['timeline','会议时间轴'],['detail','聚类与详情']].map(([key,label])=>'<button data-action="mt-pane" data-pane="'+key+'" aria-pressed="'+(v.pane===key)+'" class="'+(v.pane===key?'active':'')+'">'+label+'</button>').join('')+'</div><div class="mt-workspace" data-pane="'+v.pane+'"><section class="mt-axis-pane" aria-label="会议时间轴"><header class="mt-axis-head"><div><h3>会议时间轴 <strong>'+meetings.length+'</strong><span>次会议</span></h3><p>'+(known.length?E(known[0].date)+(known.length>1?' 至 '+E(known.at(-1).date):''):'日期未提取')+(dates.some(d=>!d.date)&&known.length?' · 含日期未提取的会议':'')+'</p></div><div>'+A('展开全部','mt-expand')+A('收起全部','mt-collapse')+'</div></header><div class="mt-axis-scroll" id="mt-axis-scroll">'+pageItems(dates,v.page,8).map(d=>{const open=v.dates.has(d.date),count=d.meetings.reduce((n,m)=>n+m.rows.length,0),limit=v.limits['date:'+d.date]||5,visible=d.meetings.slice(0,limit);return '<section class="mt-date-group"><button class="mt-date-head" data-action="mt-date" data-date="'+E(d.date)+'" aria-expanded="'+open+'">'+I(open?'down':'chevron','icon-sm')+'<time>'+E(d.date||'日期未提取')+'</time><span>'+d.meetings.length+' 次会议 · '+count+' 项议题</span></button>'+(open?'<div class="mt-date-meetings">'+visible.map(m=>mtMeeting(task,m,v)).join('')+(d.meetings.length>limit?B('再显示 '+Math.min(10,d.meetings.length-limit)+' 次会议','mt-more','ghost sm','data-key="date:'+E(d.date)+'" data-default="5"'):'')+'</div>':'')+'</section>';}).join('')+'</div>'+mtPage('dates',dates.length,v.page,8,'个日期')+'</section><aside class="mt-detail-pane"><section class="mt-topic-panel"><header><h3>议题聚类 <span>'+topics.length+' 类</span></h3><label>议题数量<select data-mt-change="order" aria-label="议题聚类排序"><option value="desc" '+(v.order==='desc'?'selected':'')+'>多 → 少</option><option value="asc" '+(v.order==='asc'?'selected':'')+'>少 → 多</option></select></label></header><nav class="mt-topic-groups" aria-label="选择议题聚类">'+pageItems(topics,v.topicPage,8).map(t=>'<button data-action="mt-topic" data-topic="'+E(t.name)+'" class="'+(v.topic===t.name?'active':'')+'" aria-pressed="'+(v.topic===t.name)+'" style="--mt-topic:'+mtColor(t.name)+'"><span class="mt-topic-dot"></span><span class="mt-topic-name" title="'+E(t.name)+'">'+E(t.name)+'</span><span><strong>'+t.rows.length+'</strong> 项 · '+mtMeetings(t.rows).length+' 次会议</span></button>').join('')+'</nav><div class="mt-topic-compact"><select data-mt-change="topic" aria-label="追踪议题聚类"><option value="">选择议题聚类</option>'+topics.map(t=>'<option value="'+E(t.name)+'" '+(v.topic===t.name?'selected':'')+'>'+E(t.name)+' · '+t.rows.length+'项 / '+mtMeetings(t.rows).length+'次会议</option>').join('')+'</select></div>'+mtPage('topics',topics.length,v.topicPage,8,'类议题')+'</section><section class="mt-detail-section"><header class="mt-detail-head '+(v.topic?'is-topic':'')+'"><div><span class="mt-eyebrow">'+(v.topic?'聚类详情':'当前会议')+'</span><h3 title="'+E(v.topic||details[0]?.title||'议题详情')+'">'+E(v.topic||details[0]?.title||'议题详情')+'</h3><p><strong>'+details.length+'</strong> 项议题'+(v.topic?' · 分布于 <strong>'+mtMeetings(details).length+'</strong> 次会议':'')+'</p></div>'+(v.topic?A('返回会议','mt-clear-topic'):'')+'</header><div class="mt-detail-scroll" id="mt-detail-scroll">'+(details.length?pageItems(details,v.detailPage,12).map(r=>mtDetail(task,r,v)).join(''):'<p class="mt-empty">点击时间轴中的会议或议题查看详情。</p>')+'</div>'+mtPage('details',details.length,v.detailPage,12,'项议题')+'</section></aside></div>';
}
function mtMeeting(task,m,v){const open=v.meetings.has(m.key),matched=v.topic&&m.rows.some(r=>mtTopic(r)===v.topic),limit=v.limits['meeting:'+m.key]||5;return '<article class="mt-meeting '+(matched?'has-match':'')+'" data-mt-meeting="'+E(m.key)+'"><button class="mt-meeting-head" data-action="mt-meeting" data-key="'+E(m.key)+'" aria-expanded="'+open+'">'+I(open?'down':'chevron','icon-sm')+'<span><strong>'+E(m.title)+'</strong><small>'+m.rows.length+' 项议题'+(matched?' · 含追踪议题':'')+'</small></span></button>'+(open?'<div class="mt-agenda">'+m.rows.slice(0,limit).map(r=>{const topic=mtTopic(r),match=v.topic===topic;return '<button class="mt-agenda-row '+(match?'is-match':'')+'" data-action="mt-agenda" data-index="'+task.result.indexOf(r)+'" style="--mt-topic:'+mtColor(topic)+'"><span class="mt-topic-dot"></span><span><strong>'+E(r.topicName||topic)+'</strong><small>'+E(topic)+'</small></span>'+I('chevron','icon-sm')+'</button>';}).join('')+(m.rows.length>limit?B('再显示 '+Math.min(20,m.rows.length-limit)+' 项议题','mt-more','ghost sm','data-key="meeting:'+E(m.key)+'" data-default="5"'):'')+'</div>':'')+'</article>';}
function mtDetail(task,r,v){const index=task.result.indexOf(r),amount=String(r.amount??'').trim(),money=!amount?'未提取到':Number.isFinite(Number.parseFloat(amount.replace(/[,，]/g,'')))?amount.replace(/\s*万元\s*$/,'')+' 万元':amount;return '<article class="mt-detail-card '+(v.focus===index?'is-focused':'')+'" data-mt-detail="'+index+'"><div class="mt-detail-date">'+E(mtDate(r)||'日期未提取')+'<span title="'+E(r.title)+'">'+E(r.title)+'</span></div><h4>'+E(r.topicName||mtTopic(r))+'</h4><p class="mt-excerpt">'+E(r.excerpt||'未提供议题内容，可核对原文。')+'</p><dl><div><dt>涉及金额</dt><dd>'+E(money)+'</dd></div><div><dt>参会人员</dt><dd>'+E(ewDisplay(r.participants)||'未提取到')+'</dd></div><div><dt>列席人员</dt><dd>'+E(ewDisplay(r.observers)||'未提取到')+'</dd></div>'+Object.entries(r.extraFields||{}).map(([k,val])=>'<div><dt>'+E(k)+'</dt><dd>'+E(ewDisplay(val)||'未提取到')+'</dd></div>').join('')+'</dl><footer><span title="'+E(file(r.doc)?.name)+'">'+E(file(r.doc)?.name)+'</span>'+awReviewLink(task,r,'查看原文')+'</footer></article>';}
function mtResultControls(task,v,rows,all){const root=document.createElement('div');root.innerHTML=aaResultTools(task);const tools=root.querySelector('.aa-result-tools'),summary=root.querySelector('.mt-filter-summary');return '<div class="mt-result-controls">'+tools.outerHTML+'<div class="aa-viewbar">'+awTabs([['meetings','会议时间轴'],['topics','议题聚类'],['all','议题清单']],v.meetingView,'aw-meeting-view')+(rows.length!==all.length?'<span>匹配 <strong>'+rows.length+'</strong> 项议题</span>':'')+'</div></div>'+(summary?.outerHTML||'');}
workbench=function(){const html=mtBase.workbench();if(state.view!=='tool'||state.toolId!=='meeting'||!currentTask()||currentTask().status==='running'||trMode())return html;const root=document.createElement('div');root.innerHTML=html;root.firstElementChild?.classList.add('mt-meeting-result');return root.innerHTML;};
awMeeting=function(task){if(!mtViews.has(task.id))av('meeting').meetingView='meetings';const v=av('meeting'),main=['risk','qa'].includes(ws().subtab)?ws().subtab:'regular';if(main!=='regular')return mtBase.awMeeting(task);const rows=awMeetingFiltered(task),all=(task.result||[]).filter(r=>file(r.doc)&&auditFileAccess(file(r.doc)).read);aaTaskView(task);mtState(task,rows);return '<div class="mt-result-nav"><div class="aa-business-tabs">'+awTabs([['regular','会议议题'],['risk','风险报告'],['qa','会议问答']],main,'meeting-tab')+'</div><header class="aa-result-heading mt-result-heading"><h2 title="'+E(task.name)+'">'+E(task.name)+'</h2>'+(task.demo?tag('演示','blue'):'')+'<span><strong>'+mtMeetings(all).length+'</strong> 次会议</span><button class="link aa-count-link" data-action="aw-all-topics"><strong>'+all.length+'</strong> 项议题</button></header></div>'+mtResultControls(task,v,rows,all)+(rows.length?awMeetingRegular(task,rows):'<div class="aa-empty"><h3>没有匹配的会议议题</h3><p>可调整搜索或筛选条件。</p>'+B('清除筛选','aw-clear','sm')+'</div>');};
awMeetingRegular=function(task,rows){if(av('meeting').meetingView==='meetings')return mtTimeline(task,rows);if(av('meeting').meetingView==='all')return mtBase.awMeetingRegular(task,rows);const ordered=mtTopics(rows).flatMap(g=>g.rows),root=document.createElement('div');root.innerHTML=mtBase.awMeetingRegular(task,ordered);root.querySelectorAll('.aw-meeting-groups>button').forEach(button=>{const matches=rows.filter(r=>mtTopic(r)===button.dataset.id),label=button.querySelector('span');if(label)label.textContent=mtMeetings(matches).length+' 次会议 · '+matches.length+' 项议题';});root.querySelectorAll('[data-aa-change=meeting-group]>option').forEach(option=>{const matches=rows.filter(r=>mtTopic(r)===option.value);option.textContent=option.value+' · '+matches.length+'项议题';});return root.innerHTML;};
awMeetingRisk=function(task){const root=document.createElement('div');root.innerHTML=mtBase.awMeetingRisk(task);const count=root.querySelector('.aa-report-head>span');if(count)count.textContent=mtMeetings((task.result||[]).filter(r=>file(r.doc)&&auditFileAccess(file(r.doc)).read)).length+' 次会议';return root.innerHTML;};
function mtLocate(task,topic,index=-1){const rows=awMeetingFiltered(task),v=mtState(task,rows),matches=rows.filter(r=>mtTopic(r)===topic),dates=mtDates(rows);if(!matches.length)return;v.topic=topic;v.focus=index>=0?index:task.result.indexOf(matches[0]);v.detailPage=Math.floor([...matches].sort((a,b)=>(mtDate(a)||'9999').localeCompare(mtDate(b)||'9999')).indexOf(task.result[v.focus])/12)+1;const groups=mtTopics(rows,v.order);v.topicPage=Math.floor(groups.findIndex(t=>t.name===topic)/8)+1;for(const row of matches){const key=mtMeetingKey(row),date=mtDate(row),dateGroup=dates.find(d=>d.date===date),m=dateGroup.meetings.find(m=>m.key===key);v.dates.add(date);v.meetings.add(key);v.limits['date:'+date]=Math.max(v.limits['date:'+date]||5,dateGroup.meetings.indexOf(m)+1);v.limits['meeting:'+key]=Math.max(v.limits['meeting:'+key]||5,m.rows.indexOf(row)+1);}const focus=task.result[v.focus]||matches[0];v.page=Math.floor(dates.findIndex(d=>d.date===mtDate(focus))/8)+1;v.pane=innerWidth<=700?'detail':v.pane;render();requestAnimationFrame(()=>{mtScrollTo('.mt-agenda-row[data-index="'+v.focus+'"]','#mt-axis-scroll');mtScrollTo('[data-mt-detail="'+v.focus+'"]','#mt-detail-scroll');mtScrollTo('.mt-topic-groups .active','.mt-topic-groups');});}
function mtScrollTo(selector,container){const node=document.querySelector(selector),area=document.querySelector(container);if(node&&area){const top=node.getBoundingClientRect().top-area.getBoundingClientRect().top+area.scrollTop-12;area.scrollTo({top:Math.max(0,top),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}
handleAction=function(action,el){if(action==='v2-reset-meeting-filter'&&state.toolId==='meeting'&&modal==='v2-meeting-filter'){editorDraft={participants:'',keywords:'',from:'',to:'',min:'',max:'',regex:false};paintModal();return;}if(action==='mt-demo'){Promise.resolve(meetingTimelineDemoReady).then(()=>{const task=state.tasks.find(t=>t.id===MEETING_TIMELINE_DEMO_TASK_ID);if(!task)return toast('演示记录已移除');openTask(task.id);av('meeting').meetingView='meetings';ws().subtab='regular';render();});return;}if(state.toolId!=='meeting'||!action.startsWith('mt-'))return mtBase.handleAction(action,el);const task=currentTask();if(!task)return;const rows=awMeetingFiltered(task),v=mtState(task,rows),data=el.dataset,scroll=document.querySelector('#mt-axis-scroll')?.scrollTop||0;
 if(action==='mt-topic')return mtLocate(task,data.topic);
 if(action==='mt-agenda'){const row=task.result[+data.index];if(rows.includes(row))return mtLocate(task,mtTopic(row),+data.index);return;}
 if(action==='mt-date'){v.dates.has(data.date)?v.dates.delete(data.date):v.dates.add(data.date);}
 if(action==='mt-meeting'){v.meetings.has(data.key)?v.meetings.delete(data.key):v.meetings.add(data.key);v.meeting=data.key;v.topic='';v.detailPage=1;v.focus=-1;}
 if(action==='mt-clear-topic'){v.topic='';v.meeting=mtMeetingKey(task.result[v.focus]||rows[0]);v.detailPage=1;v.focus=-1;}
 if(action==='mt-expand'){for(const d of mtDates(rows)){v.dates.add(d.date);d.meetings.forEach(m=>v.meetings.add(m.key));}}
 if(action==='mt-collapse'){v.dates.clear();v.meetings.clear();}
 if(action==='mt-more')v.limits[data.key]=(v.limits[data.key]||+data.default)+(+data.default===5&&data.key.startsWith('date:')?10:20);
 if(action==='mt-pane')v.pane=data.pane;
 if(action==='mt-page'){if(data.kind==='dates')v.page+=+data.step;else if(data.kind==='topics')v.topicPage+=+data.step;else v.detailPage+=+data.step;}
 render();document.querySelector('#mt-axis-scroll')?.scrollTo({top:action==='mt-page'&&data.kind==='dates'?0:scroll});if(action==='mt-page'&&data.kind==='details')document.querySelector('#mt-detail-scroll')?.scrollTo({top:0});
};
window.addEventListener('change',e=>{if(e.target.dataset.mtChange==='topic'){e.stopImmediatePropagation();const task=currentTask();if(task&&e.target.value)mtLocate(task,e.target.value);else if(task)handleAction('mt-clear-topic',{dataset:{}});return;}if(e.target.dataset.mtChange==='order'){e.stopImmediatePropagation();const task=currentTask();if(task){const v=mtState(task);v.order=e.target.value;v.topicPage=1;render();}}},true);
render();
